package sem

import "testing"

func TestTrail161ReviewCallableClassification(t *testing.T) {
	for _, snippet := range []string{
		"export declare function makeFormatter(): (value: number) => string;",
		"createHandler(): (event: Event) => void;",
	} {
		r := SearchResult{Kind: "function", Language: "typescript", Snippet: snippet,
			SymbolStartLine: 1, SymbolEndLine: 1, SnippetStartLine: 1, SnippetEndLine: 1}
		if !searchReferenceDeclaration(r) {
			t.Errorf("bodyless declaration lost its prior: %s", snippet)
		}
	}
}

func TestTrail161ReviewParsedDeclaration(t *testing.T) {
	repo := t.TempDir()
	write(t, repo, "formatter.ts", "export declare function makeFormatter(): (value: number) => string;\n")
	response, err := SearchRepository(t.Context(), repo, "test", "makeFormatter", SearchOptions{
		Worktree: true, Profile: ProfileSyntaxOnly, TopK: 5, MaxContextBytes: 20000,
	})
	if err != nil { t.Fatal(err) }
	found := false
	for _, result := range response.Results {
		if result.SymbolName != "makeFormatter" { continue }
		found = true
		t.Logf("kind=%s snippet=%q signals=%v", result.Kind, result.Snippet, result.Signals)
		if !hasSearchSignal(result, "reference-decl-prior") { t.Error("parsed declaration did not receive reference-decl-prior") }
	}
	if !found { t.Fatal("declaration not retrieved") }
}

